import pandas as pd
import re

def custom_check(series: pd.Series) -> dict:
    pattern = re.compile(r'^\$?\d*\.?\d+$')
    violations = 0
    total = len(series)

    for val in series:
        if pd.isna(val) or not pattern.match(str(val)):
            violations += 1

    if violations > 0:
        return {
            "passed": False,
            "metric": f"{violations} / {total} violations",
            "details": "Found rows containing non-numeric characters outside of allowed leading '$' and decimal points."
        }
    return {
        "passed": True,
        "metric": "0 violations",
        "details": "All values conform to quality constraint"
    }

