import pandas as pd

def custom_check(series: pd.Series) -> dict:
    total_rows = len(series)
    if total_rows == 0:
        return {"passed": True, "metric": "0 violations", "details": "Series is empty"}

    # Count rows where feedback_score contains 'Valide' (case-insensitive or exact string)
    violations = series.astype(str).str.contains('Valide', case=False, na=False).sum()

    if violations > 0:
        return {
            "passed": False,
            "metric": f"{violations} / {total_rows} violations",
            "details": f"Found {violations} anomalous text entries ('Valide') in feedback_score."
        }

    return {
        "passed": True,
        "metric": "0 violations",
        "details": "All values conform to quality constraint"
    }
